patch:
Index: Quake/src/bot/bot_ai.c
===================================================================
--- Quake/src/bot/bot_ai.c	
+++ Quake/src/bot/bot_ai.c	
@@ -1,2713 +1,2740 @@
 #include "quakedef.h"
 #include "bot_main.h"
 #include "bot_ai.h"
 #include "bot_nav2.h"
 #include "bot_combat.h"
 
 #define BOT_MAX_ROAM_POINTS 512
 #define BOT_GOAL_REACH_DIST 56.f
 #define BOT_ENEMY_FORGET_TIME 2.5
 #define BOT_NAV_CACHE_MAX_AGE 0.15
 #define BOT_NAV_CACHE_REUSE_DIST 48.f
 #define BOT_ITEM_SCAN_SHARDS 4
 #define BOT_TARGET_EVAL_CACHE_TTL 0.1
 #define BOT_TARGET_EVAL_INVALIDATE_DIST 64.f
 
 typedef enum bot_item_type_e
 {
 	BOT_ITEM_NONE = 0,
 	BOT_ITEM_WEAPON,
 	BOT_ITEM_AMMO,
 	BOT_ITEM_HEALTH,
 	BOT_ITEM_ARMOR,
 	BOT_ITEM_POWERUP
 } bot_item_type_t;
 
 typedef enum bot_ammo_type_e
 {
 	BOT_AMMO_NONE = 0,
 	BOT_AMMO_SHELLS,
 	BOT_AMMO_NAILS,
 	BOT_AMMO_ROCKETS,
 	BOT_AMMO_CELLS
 } bot_ammo_type_t;
 
 typedef struct bot_item_candidate_s
 {
 	int edict_index;
 	bot_item_type_t type;
 } bot_item_candidate_t;
 
 static vec3_t g_roam_points[BOT_MAX_ROAM_POINTS];
 static int g_roam_count;
 static bot_item_candidate_t g_item_candidates[MAX_EDICTS];
 static int g_item_candidate_count;
 static int g_item_candidate_last_num_edicts;
 
 static void BotAI_RebuildItemCandidates (void);
 static void BotAI_MaintainItemCandidates (void);
 
 static qboolean BotAI_ShouldUseNav2 (void)
 {
 	return BotNav_IsLoaded ();
 }
 
 static const char *BotAI_TryGetString (int string_id)
 {
 	if (!qcvm)
 		return NULL;
 	if (string_id >= 0 && string_id < qcvm->stringssize)
 		return PR_GetString (string_id);
 	if (string_id < 0 && string_id >= -qcvm->numknownstrings)
 		return PR_GetString (string_id);
 	return NULL;
 }
 
 static qboolean BotAI_IsFailedEdge (const bot_state_t *bot, int from, int to)
 {
 	int i;
 	if (!bot || from < 0 || to < 0)
 		return false;
 
 	for (i = 0; i < (int) countof (bot->failed_edge_from); ++i)
 	{
 		if (bot->failed_edge_until[i] < qcvm->time)
 			continue;
 		if (bot->failed_edge_from[i] == from && bot->failed_edge_to[i] == to)
 			return true;
 	}
 	return false;
 }
 
 static void BotAI_RegisterFailedEdge (bot_state_t *bot, int from, int to)
 {
 	int i;
 	int slot;
 	if (!bot || from < 0 || to < 0)
 		return;
 
 	for (i = 0; i < (int) countof (bot->failed_edge_from); ++i)
 	{
 		if (bot->failed_edge_from[i] == from && bot->failed_edge_to[i] == to)
 		{
 			bot->failed_edge_until[i] = qcvm->time + 6.0;
 			return;
 		}
 	}
 
 	slot = bot->failed_edge_cursor % (int) countof (bot->failed_edge_from);
 	bot->failed_edge_cursor++;
 	bot->failed_edge_from[slot] = from;
 	bot->failed_edge_to[slot] = to;
 	bot->failed_edge_until[slot] = qcvm->time + 6.0;
 }
 
 static qboolean BotAI_IsFailedGoalNode (const bot_state_t *bot, int node)
 {
 	if (!bot || node < 0)
 		return false;
 	return bot->failed_goal_node == node && qcvm->time < bot->failed_goal_node_until;
 }
 
 static void BotAI_ResetNearestCacheEntry (bot_nav_nearest_cache_t *cache)
 {
 	if (!cache)
 		return;
 	cache->node_index = -1;
 	cache->nav_node_count = -1;
 	cache->timestamp = 0.0;
 	VectorCopy (vec3_origin, cache->sampled_origin);
 }
 
 static int BotAI_FindNearestNodeCached (bot_nav_nearest_cache_t *cache, const vec3_t pos)
 {
 	int nav_node_count;
 	double age = 0.0;
 
 	if (!cache)
 		return BotNav_FindNearestNode (pos);
 
 	nav_node_count = BotNav_NodeCount ();
 	if (cache->nav_node_count != nav_node_count)
 		cache->node_index = -1;
 
 	if (cache->node_index >= 0)
 	{
 		vec3_t delta;
 		float dist;
 
 		VectorSubtract (pos, cache->sampled_origin, delta);
 		dist = VectorLength (delta);
 		age = qcvm->time - cache->timestamp;
 		if (dist <= BOT_NAV_CACHE_REUSE_DIST && age >= 0.0 && age <= BOT_NAV_CACHE_MAX_AGE)
 			return cache->node_index;
 	}
 
 	cache->node_index = BotNav_FindNearestNode (pos);
 	cache->nav_node_count = nav_node_count;
 	cache->timestamp = qcvm->time;
 	VectorCopy (pos, cache->sampled_origin);
 	return cache->node_index;
 }
 
 static int BotAI_FindNearestSelfNode (bot_state_t *bot, edict_t *self)
 {
 	if (!bot || !self)
 		return -1;
 	return BotAI_FindNearestNodeCached (&bot->self_nearest_cache, self->v.origin);
 }
 
 static int BotAI_FindNearestGoalNode (bot_state_t *bot, const vec3_t goal_pos)
 {
 	if (!bot)
 		return BotNav_FindNearestNode (goal_pos);
 	return BotAI_FindNearestNodeCached (&bot->goal_nearest_cache, goal_pos);
 }
 
 static qboolean BotAI_CanPathToPos (bot_state_t *bot, edict_t *self, const vec3_t goal_pos, qboolean reject_failed_first_edge)
 {
 	int start;
 	int goal;
 	bot_path_t path;
 
 	if (!bot || !self || !BotAI_ShouldUseNav2 ())
 		return true;
 
 	start = BotAI_FindNearestSelfNode (bot, self);
 	goal = BotAI_FindNearestGoalNode (bot, goal_pos);
 	if (start < 0 || goal < 0)
 		return false;
 	if (!BotNav_FindPath (start, goal, &path))
 		return false;
 	if (path.count <= 1)
 		return false;
 	if (reject_failed_first_edge && BotAI_IsFailedEdge (bot, path.nodes[0], path.nodes[1]))
 		return false;
 
 	return true;
 }
 
 static float BotAI_Noise01 (uint32_t seed)
 {
 	seed ^= seed >> 16;
 	seed *= 0x7feb352dU;
 	seed ^= seed >> 15;
 	seed *= 0x846ca68bU;
 	seed ^= seed >> 16;
 	return (float) (seed & 0xffffU) / 65535.f;
 }
 
 static float BotAI_Random01 (const bot_state_t *bot, uint32_t salt)
 {
 	uint32_t frame = (uint32_t) host_framecount;
 	uint32_t botseed = bot ? (uint32_t) (bot->clientnum + 1) * 1315423911U : 0U;
 	return BotAI_Noise01 (frame * 1664525U + botseed + salt * 374761393U);
 }
 
 static qboolean BotAI_HasPrefix (const char *value, const char *prefix)
 {
 	return q_strncasecmp (value, prefix, strlen (prefix)) == 0;
 }
 
 static qboolean BotAI_IsAlivePlayer (edict_t *ent)
 {
 	if (!ent)
 		return false;
 	if (ent->free)
 		return false;
 	if (ent->v.health <= 0.f)
 		return false;
 	if ((int) ent->v.deadflag != DEAD_NO)
 		return false;
 	return true;
 }
 
 static qboolean BotAI_IsTeammate (edict_t *self, edict_t *other)
 {
 	if (!self || !other)
 		return false;
 	if (!teamplay.value)
 		return false;
 	if ((int) self->v.team <= 0 || (int) other->v.team <= 0)
 		return false;
 	return (int) self->v.team == (int) other->v.team;
 }
 
 static qboolean BotAI_IsCompanionMode (const bot_state_t *bot)
 {
 	int i;
 	int humans = 0;
 
 	if (!bot || cls.state == ca_dedicated)
 		return false;
 	if (deathmatch.value)
 		return false;
 
 	for (i = 0; i < svs.maxclients; ++i)
 	{
 		const client_t *candidate_client = &svs.clients[i];
 		if (!candidate_client->active || !candidate_client->spawned || candidate_client->isbot || !candidate_client->edict)
 			continue;
 		if (!BotAI_IsAlivePlayer (candidate_client->edict))
 			continue;
 		humans++;
 	}
 
 	if (coop.value)
 		return humans > 0;
 
 	return humans == 1;
 }
 
 static float BotAI_ClampedAgility (const bot_state_t *bot)
 {
 	float agility = bot ? bot->agility : 0.f;
 
 	if (agility <= 0.f)
 		agility = 1.f;
 	return CLAMP (0.4f, agility, 1.4f);
 }
 
 static edict_t *BotAI_FindLeaderPlayer (const bot_state_t *bot, edict_t *self)
 {
 	int i;
 	float best_dist = 999999.f;
 	edict_t *best = NULL;
 
 	if (!bot || !self || !BotAI_IsCompanionMode (bot))
 		return NULL;
 
 	for (i = 0; i < svs.maxclients; ++i)
 	{
 		client_t *candidate_client = &svs.clients[i];
 		edict_t *candidate;
 		vec3_t delta;
 		float dist;
 
 		if (!candidate_client->active || !candidate_client->spawned || candidate_client->isbot || !candidate_client->edict)
 			continue;
 		candidate = candidate_client->edict;
 		if (!BotAI_IsAlivePlayer (candidate))
 			continue;
 		VectorSubtract (candidate->v.origin, self->v.origin, delta);
 		dist = VectorLength (delta);
 		if (dist < best_dist)
 		{
 			best_dist = dist;
 			best = candidate;
 		}
 	}
 
 	return best;
 }
 
 static qboolean BotAI_IsEntityMoving (edict_t *ent, float min_speed)
 {
 	vec3_t velocity;
 
 	if (!ent)
 		return false;
 
 	VectorCopy (ent->v.velocity, velocity);
 	velocity[2] = 0.f;
 	return VectorLength (velocity) > min_speed;
 }
 
 static qboolean BotAI_UpdateDamageAlert (float current_health, float *last_health)
 {
 	qboolean took_damage = false;
 
 	if (!last_health)
 		return false;
 
 	if (*last_health > 0.f && current_health < (*last_health - 2.f))
 		took_damage = true;
 
 	*last_health = current_health;
 	return took_damage;
 }
 
 static qboolean BotAI_UpdateCompanionAlert (bot_state_t *bot, edict_t *self, edict_t *leader)
 {
 	qboolean alerted = false;
 
 	if (!bot || !self)
 		return false;
 
 	if (BotAI_UpdateDamageAlert (self->v.health, &bot->last_health))
 	{
 		VectorCopy (self->v.origin, bot->alert_pos);
 		bot->alert_until = qcvm->time + 3.0;
 		alerted = true;
 	}
 
 	if (leader && BotAI_UpdateDamageAlert (leader->v.health, &bot->last_leader_health))
 	{
 		VectorCopy (leader->v.origin, bot->alert_pos);
 		bot->alert_until = qcvm->time + 3.0;
 		alerted = true;
 	}
 	else if (!leader)
 	{
 		bot->last_leader_health = 0.f;
 	}
 
 	return alerted;
 }
 
 static qboolean BotAI_CanSee (edict_t *self, edict_t *other)
 {
 	vec3_t start;
 	vec3_t end;
 	trace_t tr;
 
 	if (!self || !other)
 		return false;
 
 	VectorAdd (self->v.origin, self->v.view_ofs, start);
 	VectorAdd (other->v.origin, other->v.view_ofs, end);
 	tr = SV_Move (start, vec3_origin, vec3_origin, end, MOVE_NOMONSTERS, self);
 	return tr.fraction >= 1.f;
 }
 
 static void BotAI_ClearTargetEvalCache (bot_state_t *bot)
 {
 	int i;
 
 	if (!bot)
 		return;
 
 	for (i = 0; i < BOT_TARGET_EVAL_CACHE_SIZE; ++i)
 	{
 		bot->target_eval_cache[i].target_entnum = -1;
 		bot->target_eval_cache[i].timestamp = 0.0;
 		bot->target_eval_cache[i].has_visibility = false;
 		bot->target_eval_cache[i].visibility = false;
 		bot->target_eval_cache[i].has_pathable = false;
 		bot->target_eval_cache[i].pathable = false;
 	}
 	bot->target_eval_origin_valid = false;
 	VectorCopy (vec3_origin, bot->target_eval_origin);
 }
 
 static bot_target_eval_cache_entry_t *BotAI_FindTargetEvalCacheEntry (bot_state_t *bot, int target_entnum)
 {
 	int i;
 	bot_target_eval_cache_entry_t *oldest = NULL;
 	double oldest_time = 0.0;
 
 	if (!bot || target_entnum < 0)
 		return NULL;
 
 	for (i = 0; i < BOT_TARGET_EVAL_CACHE_SIZE; ++i)
 	{
 		bot_target_eval_cache_entry_t *entry = &bot->target_eval_cache[i];
 		if (entry->target_entnum == target_entnum)
 			return entry;
 		if (entry->target_entnum < 0)
 			return entry;
 		if (!oldest || entry->timestamp < oldest_time)
 		{
 			oldest = entry;
 			oldest_time = entry->timestamp;
 		}
 	}
 
 	return oldest;
 }
 
 static void BotAI_PrepareTargetEvalCache (bot_state_t *bot, edict_t *self)
 {
 	vec3_t delta;
 
 	if (!bot || !self)
 		return;
 
 	if (!bot->target_eval_origin_valid)
 	{
 		VectorCopy (self->v.origin, bot->target_eval_origin);
 		bot->target_eval_origin_valid = true;
 		return;
 	}
 
 	VectorSubtract (self->v.origin, bot->target_eval_origin, delta);
 	if (DotProduct (delta, delta) > BOT_TARGET_EVAL_INVALIDATE_DIST * BOT_TARGET_EVAL_INVALIDATE_DIST)
 	{
 		BotAI_ClearTargetEvalCache (bot);
 		VectorCopy (self->v.origin, bot->target_eval_origin);
 		bot->target_eval_origin_valid = true;
 	}
 }
 
 static qboolean BotAI_CanSeeCached (bot_state_t *bot, edict_t *self, edict_t *viewer, edict_t *target)
 {
 	bot_target_eval_cache_entry_t *entry;
 	int target_entnum;
 	qboolean visible;
 
 	if (!viewer || !target)
 		return false;
 	if (!bot || viewer != self)
 		return BotAI_CanSee (viewer, target);
 
 	BotAI_PrepareTargetEvalCache (bot, self);
 	target_entnum = NUM_FOR_EDICT (target);
 	entry = BotAI_FindTargetEvalCacheEntry (bot, target_entnum);
 	if (entry && entry->target_entnum == target_entnum && entry->has_visibility && (qcvm->time - entry->timestamp) <= BOT_TARGET_EVAL_CACHE_TTL)
 		return entry->visibility;
 
 	visible = BotAI_CanSee (viewer, target);
 	if (entry)
 	{
 		entry->target_entnum = target_entnum;
 		entry->timestamp = qcvm->time;
 		entry->has_visibility = true;
 		entry->visibility = visible;
 	}
 	return visible;
 }
 
 static qboolean BotAI_CanPathToTargetCached (bot_state_t *bot, edict_t *self, edict_t *target)
 {
 	bot_target_eval_cache_entry_t *entry;
 	int target_entnum;
 	qboolean pathable;
 
 	if (!bot || !self || !target)
 		return false;
 
 	BotAI_PrepareTargetEvalCache (bot, self);
 	target_entnum = NUM_FOR_EDICT (target);
 	entry = BotAI_FindTargetEvalCacheEntry (bot, target_entnum);
 	if (entry && entry->target_entnum == target_entnum && entry->has_pathable && (qcvm->time - entry->timestamp) <= BOT_TARGET_EVAL_CACHE_TTL)
 		return entry->pathable;
 
 	pathable = BotAI_CanPathToPos (bot, self, target->v.origin, true);
 	if (entry)
 	{
 		entry->target_entnum = target_entnum;
 		entry->timestamp = qcvm->time;
 		entry->has_pathable = true;
 		entry->pathable = pathable;
 	}
 	return pathable;
 }
 
 static qboolean BotAI_IsMonsterEnemyCandidate (edict_t *ent)
 {
 	const char *classname;
 
 	if (!ent || ent->free)
 		return false;
 	if (ent->v.health <= 0.f)
 		return false;
 	if ((int) ent->v.takedamage == DAMAGE_NO)
 		return false;
 	if (((int) ent->v.flags & FL_MONSTER) == 0)
 		return false;
 
 	classname = BotAI_TryGetString ((int) ent->v.classname);
 	if (classname && BotAI_HasPrefix (classname, "monster_"))
 		return true;
 
 	return true;
 }
 
 static qboolean BotAI_IsInterestingRoamClass (const char *classname)
 {
 	if (!classname || !classname[0])
 		return false;
 
 	if (BotAI_HasPrefix (classname, "info_player_"))
 		return true;
 	if (BotAI_HasPrefix (classname, "weapon_"))
 		return true;
 	if (BotAI_HasPrefix (classname, "ammo_"))
 		return true;
 	if (q_strcasestr (classname, "health"))
 		return true;
 	if (q_strcasestr (classname, "armor"))
 		return true;
 	if (q_strcasestr (classname, "artifact"))
 		return true;
 
 	return false;
 }
 
 static void BotAI_AddRoamPoint (const vec3_t point)
 {
 	int i;
 
 	if (g_roam_count >= BOT_MAX_ROAM_POINTS)
 		return;
 
 	for (i = 0; i < g_roam_count; ++i)
 	{
 		vec3_t delta;
 		VectorSubtract (point, g_roam_points[i], delta);
 		if (DotProduct (delta, delta) < 80.f * 80.f)
 			return;
 	}
 
 	VectorCopy (point, g_roam_points[g_roam_count]);
 	g_roam_count++;
 }
 
 void BotAI_OnMapSpawn (void)
 {
 	int i;
 
 	g_roam_count = 0;
 	BotAI_RebuildItemCandidates ();
 
 	for (i = 1; i < qcvm->num_edicts; ++i)
 	{
 		edict_t *ent = EDICT_NUM (i);
 		const char *classname;
 		vec3_t point;
 
 		if (ent->free)
 			continue;
 
 			classname = BotAI_TryGetString ((int) ent->v.classname);
 			if (!classname)
 				continue;
 			if (!BotAI_IsInterestingRoamClass (classname))
 				continue;
 
 		VectorCopy (ent->v.origin, point);
 		point[2] += 20.f;
 		BotAI_AddRoamPoint (point);
 	}
 
 	for (i = 0; i < svs.maxclients; ++i)
 	{
 		client_t *client = &svs.clients[i];
 		if (!client->active || !client->edict)
 			continue;
 		BotAI_AddRoamPoint (client->edict->v.origin);
 	}
 
 	if (!g_roam_count)
 	{
 		vec3_t fallback = {0.f, 0.f, 32.f};
 		BotAI_AddRoamPoint (fallback);
 	}
 
 	if (bot_think_debug.value)
 		Con_Printf ("BotAI: collected %d roam points, %d item candidates\n", g_roam_count, g_item_candidate_count);
 }
 
 static bot_item_type_t BotAI_ClassifyItem (const char *classname)
 {
 	if (!classname || !classname[0])
 		return BOT_ITEM_NONE;
 	if (BotAI_HasPrefix (classname, "weapon_"))
 		return BOT_ITEM_WEAPON;
 	if (BotAI_HasPrefix (classname, "ammo_"))
 		return BOT_ITEM_AMMO;
 	if (q_strcasestr (classname, "item_health"))
 		return BOT_ITEM_HEALTH;
 	if (q_strcasestr (classname, "armor"))
 		return BOT_ITEM_ARMOR;
 	if (q_strcasestr (classname, "artifact") || q_strcasestr (classname, "powerup"))
 		return BOT_ITEM_POWERUP;
 	return BOT_ITEM_NONE;
 }
 
 static void BotAI_RebuildItemCandidates (void)
 {
 	int i;
 
 	g_item_candidate_count = 0;
 	g_item_candidate_last_num_edicts = qcvm ? qcvm->num_edicts : 0;
 	if (!qcvm)
 		return;
 
 	for (i = svs.maxclients + 1; i < qcvm->num_edicts; ++i)
 	{
 		edict_t *ent = EDICT_NUM (i);
 		const char *classname;
 		bot_item_type_t type;
 
 		if (!ent || ent->free)
 			continue;
 
 		classname = BotAI_TryGetString ((int) ent->v.classname);
 		type = BotAI_ClassifyItem (classname);
 		if (type == BOT_ITEM_NONE)
 			continue;
 		if (g_item_candidate_count >= (int) countof (g_item_candidates))
 			break;
 
 		g_item_candidates[g_item_candidate_count].edict_index = i;
 		g_item_candidates[g_item_candidate_count].type = type;
 		g_item_candidate_count++;
 	}
 }
 
 static void BotAI_MaintainItemCandidates (void)
 {
 	int i;
 
 	if (!qcvm)
 		return;
 	if (g_item_candidate_last_num_edicts > qcvm->num_edicts)
 	{
 		BotAI_RebuildItemCandidates ();
 		return;
 	}
 	if (g_item_candidate_last_num_edicts == qcvm->num_edicts)
 		return;
 
 	for (i = q_max (g_item_candidate_last_num_edicts, svs.maxclients + 1); i < qcvm->num_edicts; ++i)
 	{
 		edict_t *ent = EDICT_NUM (i);
 		const char *classname;
 		bot_item_type_t type;
 
 		if (!ent || ent->free)
 			continue;
 
 		classname = BotAI_TryGetString ((int) ent->v.classname);
 		type = BotAI_ClassifyItem (classname);
 		if (type == BOT_ITEM_NONE)
 			continue;
 		if (g_item_candidate_count >= (int) countof (g_item_candidates))
 			break;
 
 		g_item_candidates[g_item_candidate_count].edict_index = i;
 		g_item_candidates[g_item_candidate_count].type = type;
 		g_item_candidate_count++;
 	}
 
 	g_item_candidate_last_num_edicts = qcvm->num_edicts;
 }
 
 static int BotAI_WeaponForClassname (const char *classname)
 {
 	if (!classname)
 		return 0;
 	if (q_strcasecmp (classname, "weapon_shotgun") == 0)
 		return IT_SHOTGUN;
 	if (q_strcasecmp (classname, "weapon_supershotgun") == 0)
 		return IT_SUPER_SHOTGUN;
 	if (q_strcasecmp (classname, "weapon_nailgun") == 0)
 		return IT_NAILGUN;
 	if (q_strcasecmp (classname, "weapon_supernailgun") == 0)
 		return IT_SUPER_NAILGUN;
 	if (q_strcasecmp (classname, "weapon_grenadelauncher") == 0)
 		return IT_GRENADE_LAUNCHER;
 	if (q_strcasecmp (classname, "weapon_rocketlauncher") == 0)
 		return IT_ROCKET_LAUNCHER;
 	if (q_strcasecmp (classname, "weapon_lightning") == 0)
 		return IT_LIGHTNING;
 	return 0;
 }
 
 static bot_ammo_type_t BotAI_AmmoForClassname (const char *classname)
 {
 	if (!classname)
 		return BOT_AMMO_NONE;
