 	if (q_strcasestr (classname, "nail"))
 		return BOT_AMMO_NAILS;
 	if (q_strcasestr (classname, "rocket"))
 		return BOT_AMMO_ROCKETS;
 	if (q_strcasestr (classname, "cell"))
