 static edict_t *BotAI_FindBestItem (bot_state_t *bot, edict_t *self, qboolean enemy_visible, qboolean urgent_override)
 {
 	int i;
 	float best_score = 0.f;
 	edict_t *best = NULL;
 	const int frame_shard = ((int) host_framecount) % BOT_ITEM_SCAN_SHARDS;
 	const int bot_shard = bot ? (bot->clientnum % BOT_ITEM_SCAN_SHARDS) : 0;
 
 	BotAI_MaintainItemCandidates ();
 
 	for (i = 0; i < g_item_candidate_count; ++i)
 	{
 		const bot_item_candidate_t *candidate = &g_item_candidates[i];
 		edict_t *item = EDICT_NUM (candidate->edict_index);
 		const char *classname;
 		vec3_t delta;
 		float dist;
 		float score;
 		qboolean item_reachable;
 
 		if (!urgent_override && !enemy_visible && bot_shard != frame_shard)
 			continue;
 		if (!item || item->free)
 			continue;
 		if ((int) item->v.solid == SOLID_NOT)
 			continue;
 		if (bot->failed_goal_item == item && qcvm->time < bot->failed_goal_item_until)
 			continue;
 		if (BotAI_ShouldUseNav2 ())
 		{
 			int item_node = BotAI_FindNearestGoalNode (bot, item->v.origin);
 			if (BotAI_IsFailedGoalNode (bot, item_node))
 				continue;
 		}
 
 		classname = BotAI_TryGetString ((int) item->v.classname);
 		if (!classname)
 			continue;
 		if (candidate->type == BOT_ITEM_NONE)
 			continue;
 
 		VectorSubtract (item->v.origin, self->v.origin, delta);
 		dist = VectorLength (delta);
 		if (dist > 2200.f)
 			continue;
 
 		item_reachable = BotAI_ItemPotentiallyReachable (bot, self, item);
 		if (!item_reachable)
 			continue;
 		score = BotAI_ItemScore (bot, self, item, classname, enemy_visible, dist, item_reachable);
 		if (score > best_score)
 		{
 			best_score = score;
 			best = item;
 		}
 	}
 
 	return best;
 }
 
 static edict_t *BotAI_FindBestEnemy (bot_state_t *bot, edict_t *self, qboolean *out_visible)
 {
 	int i;
 	float best_score = -1.f;
 	edict_t *best = NULL;
 	qboolean companion_mode;
 
 	*out_visible = false;
 	companion_mode = BotAI_IsCompanionMode (bot);
 
 	for (i = 0; i < svs.maxclients; ++i)
 	{
 		client_t *client = &svs.clients[i];
 		edict_t *candidate;
 		vec3_t delta;
 		float dist;
 		float score;
 		qboolean visible;
 
 		if (!client->active || !client->spawned)
 			continue;
 		if (i == bot->clientnum)
 			continue;
 
 		candidate = client->edict;
 		if (!BotAI_IsAlivePlayer (candidate))
 			continue;
 		if (BotAI_IsTeammate (self, candidate))
 			continue;
 		if (companion_mode)
 			continue;
 		VectorSubtract (candidate->v.origin, self->v.origin, delta);
 		dist = VectorLength (delta);
 		if (dist > 2500.f)
 			continue;
 		visible = BotAI_CanSeeCached (bot, self, self, candidate);
 		if (!visible && dist > 900.f)
 			continue;
 		if (!visible && BotAI_ShouldUseNav2 () && !BotAI_CanPathToTargetCached (bot, self, candidate))
 			continue;
 
 		score = 2600.f - dist;
 		score += candidate->v.frags * 2.f;
 		if (visible)
 			score += 250.f;
 		else
 			score -= 180.f;
 		if (score > best_score)
 		{
 			best_score = score;
 			best = candidate;
 			*out_visible = visible;
 		}
 	}
 
 	if (companion_mode)
 	{
 		for (i = svs.maxclients + 1; i < qcvm->num_edicts; ++i)
 		{
 			edict_t *candidate = EDICT_NUM (i);
 			vec3_t delta;
 			float dist;
 			float score;
 			qboolean visible;
 
 			if (!BotAI_IsMonsterEnemyCandidate (candidate))
 				continue;
 
 			VectorSubtract (candidate->v.origin, self->v.origin, delta);
 			dist = VectorLength (delta);
 			if (dist > 2500.f)
 				continue;
 			visible = BotAI_CanSeeCached (bot, self, self, candidate);
 			if (!visible && dist > 900.f)
 				continue;
 			if (!visible && BotAI_ShouldUseNav2 () && !BotAI_CanPathToTargetCached (bot, self, candidate))
 				continue;
 
 			score = 2300.f - dist;
 			if (visible)
 				score += 200.f;
 			else
 				score -= 150.f;
 			if (score > best_score)
 			{
 				best_score = score;
 				best = candidate;
 				*out_visible = visible;
 			}
 		}
 	}
 
 	return best;
 }
 
 static edict_t *BotAI_FindThreatNearPoint (bot_state_t *bot, edict_t *self, edict_t *leader, const vec3_t focus, qboolean *out_visible)
 {
 	int i;
 	float best_score = -1.f;
 	edict_t *best = NULL;
 
 	if (out_visible)
 		*out_visible = false;
 	if (!bot || !self)
 		return NULL;
 
 	for (i = svs.maxclients + 1; i < qcvm->num_edicts; ++i)
 	{
 		edict_t *candidate = EDICT_NUM (i);
 		vec3_t to_focus;
 		vec3_t to_self;
 		float focus_dist;
 		float self_dist;
 		float score;
 		qboolean visible;
 		qboolean leader_visible;
 
 		if (!BotAI_IsMonsterEnemyCandidate (candidate))
 			continue;
 
 		VectorSubtract (candidate->v.origin, focus, to_focus);
 		focus_dist = VectorLength (to_focus);
 		if (focus_dist > 1200.f)
 			continue;
 
 		VectorSubtract (candidate->v.origin, self->v.origin, to_self);
 		self_dist = VectorLength (to_self);
 		visible = BotAI_CanSeeCached (bot, self, self, candidate);
 		leader_visible = leader ? BotAI_CanSeeCached (bot, self, leader, candidate) : false;
 		if (!visible && !leader_visible && BotAI_ShouldUseNav2 () && !BotAI_CanPathToTargetCached (bot, self, candidate))
 			continue;
 
 		score = 1500.f - focus_dist - self_dist * 0.2f;
 		if (visible)
 			score += 250.f;
 		else if (leader_visible)
 			score += 125.f;
 
 		if (score > best_score)
 		{
 			best_score = score;
 			best = candidate;
 			if (out_visible)
 				*out_visible = visible;
 		}
 	}
 
 	return best;
 }
 
 static float BotAI_AngleDelta (float from, float to)
 {
 	float delta = anglemod (to) - anglemod (from);
 	if (delta > 180.f)
 		delta -= 360.f;
 	if (delta < -180.f)
 		delta += 360.f;
 	return delta;
 }
 
 static float BotAI_ApproachAngle (float from, float to, float max_step)
 {
 	float delta = BotAI_AngleDelta (from, to);
 	if (delta > max_step)
 		delta = max_step;
 	if (delta < -max_step)
 		delta = -max_step;
 	return anglemod (from + delta);
 }
 
